t.script:
(function(){
  var KK = document.getElementById('pr-k').getAttribute('data-k');
  /* Relais Render : page ouverte via la clé responsables, sans compte Odoo —
     /web/dataset/call_kw répond « Session expired » hors backend. */
  var RPC = 'https://ocr-pesee-webhook.onrender.com/heures/rpc';
  function rpcAction(actionId, ctx){
    return fetch(RPC,{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({action_id:actionId, ctx:ctx})});
  }
  function handleErr(d){
    var m = (d.error && ((d.error.data && d.error.data.message) || d.error.message)) || '';
    alert('Échec : ' + m);
  }
  function repond(id, dec, rep){
    rpcAction(2014, {active_model:'x_demande_conge',dc_id:id,dc_decision:dec,dc_reponse:rep,hj_k:KK}).then(function(r){return r.json();}).then(function(d){
      if(d.error){ handleErr(d); return; }
      location.reload();
    }).catch(function(){ alert('Échec réseau'); });
  }
  var pop = document.getElementById('prPop');
  var curEmp = null, curDate = null, curType = 'travail';
  function f2t(v){
    v = parseFloat(v || 0);
    if(!v){ return ''; }
    var h = Math.floor(v), m = Math.round((v - h) * 60);
    return String(h).padStart(2,'0') + ':' + String(m).padStart(2,'0');
  }
  function t2f(v){ if(!v){ return 0; } var p = v.split(':'); return parseInt(p[0],10) + parseInt(p[1],10)/60; }
  var curPer = 'journee';
  function selPer(pp){
    curPer = pp;
    document.querySelectorAll('#prPer button').forEach(function(b){ b.classList.toggle('on', b.getAttribute('data-p') === pp); });
    document.getElementById('prCz').style.display = (pp === 'horaires') ? 'grid' : 'none';
  }
  function selType(t){
    curType = t;
    document.querySelectorAll('#prTyp button').forEach(function(b){ b.classList.toggle('on', b.getAttribute('data-t') === t); });
    var conge = (t !== 'travail' && t !== 'repos');
    document.getElementById('prPer').style.display = conge ? 'grid' : 'none';
    document.getElementById('prHzone').style.display = (t === 'travail') ? 'grid' : 'none';
    if(!conge){ document.getElementById('prCz').style.display = 'none'; }
    else { selPer(curPer); }
  }
  var prOuverture = false;
  function openCell(td){
    prOuverture = true;
    curEmp = td.getAttribute('data-emp');
    curDate = td.getAttribute('data-date');
    var dd = curDate.split('-');
    document.getElementById('prPopT').textContent = td.getAttribute('data-ename') + ' — ' + dd[2] + '/' + dd[1] + '/' + dd[0];
    document.getElementById('prM1').value = f2t(td.getAttribute('data-md'));
    document.getElementById('prM2').value = f2t(td.getAttribute('data-mf'));
    document.getElementById('prA1').value = f2t(td.getAttribute('data-ad'));
    document.getElementById('prA2').value = f2t(td.getAttribute('data-af'));
    curPer = 'journee';
    selPer('journee');
    selType(td.getAttribute('data-type') || 'travail');
    prOuverture = false;
    pop.classList.add('show');
  }
  document.getElementById('prPopCancel').addEventListener('click', function(){ pop.classList.remove('show'); });
  pop.addEventListener('click', function(e){ if(e.target === pop){ pop.classList.remove('show'); } });
  document.getElementById('prPopSave').addEventListener('click', function(){
    if(!curEmp){ return; }
    var btn = document.getElementById('prPopSave');
    btn.disabled = true;
    var conge = (curType !== 'travail' && curType !== 'repos');
    if(conge && curPer === 'horaires'){
      var cd = t2f(document.getElementById('prC1').value), ca = t2f(document.getElementById('prC2').value);
      if(!(cd < ca)){ alert('Renseignez les horaires du congé (début avant fin).'); return; }
    }
    rpcAction(2012, {active_model:'x_heures_jour', hj_emp:parseInt(curEmp,10), hj_date:curDate, hj_type:curType,
      hj_periode:(conge ? curPer : 'journee'),
      hj_c_de:(conge ? t2f(document.getElementById('prC1').value) : 0),
      hj_c_a:(conge ? t2f(document.getElementById('prC2').value) : 0),
      hj_m_deb:(curType === 'travail' ? t2f(document.getElementById('prM1').value) : 0),
      hj_m_fin:(curType === 'travail' ? t2f(document.getElementById('prM2').value) : 0),
      hj_am_deb:(curType === 'travail' ? t2f(document.getElementById('prA1').value) : 0),
      hj_am_fin:(curType === 'travail' ? t2f(document.getElementById('prA2').value) : 0),
      hj_k:KK}).then(function(r){return r.json();}).then(function(d){
      btn.disabled = false;
      if(d.error){ handleErr(d); return; }
      location.reload();
    }).catch(function(){ btn.disabled = false; alert('Échec réseau'); });
  });
  document.addEventListener('click', function(e){
    var ok = e.target.closest('.pr-ok');
    if(ok){ if(confirm('Approuver cette demande ? Les jours seront inscrits automatiquement.')){ repond(parseInt(ok.getAttribute('data-id')), 'approuve', ''); } return; }
    var no = e.target.closest('.pr-no');
    if(no){ var m = prompt('Motif du refus (transmis au salarié) :', ''); if(m !== null){ repond(parseInt(no.getAttribute('data-id')), 'refuse', m); } return; }
    var tb = e.target.closest('#prTyp button');
    if(tb){ selType(tb.getAttribute('data-t')); return; }
    var pb = e.target.closest('#prPer button');
    if(pb){ selPer(pb.getAttribute('data-p')); return; }
    var td = e.target.closest('td[data-emp]');
    if(td){ openCell(td); }
  });
})();
